      "why_included": "The category-defining platform that most field service SMBs evaluate. Investors will ask about ServiceTitan first."
    },
    {
      "name": "Jobber",
      "slug": "jobber",
      "category": "direct",
      "description": "SMB-focused field service management software covering scheduling, invoicing, client management, and payments. Canadian-headquartered with strong US presence.",
      "key_differentiators": ["SMB-friendly pricing and UX", "Fast onboarding", "Strong brand in home services", "Payments integration"],
      "why_included": "Most direct SMB competitor. Investors will compare Cadence to Jobber because of overlapping target customer."
    },
    {
      "name": "Housecall Pro",
      "slug": "housecall-pro",
      "category": "direct",
      "description": "All-in-one field service app for home service pros covering scheduling, dispatch, invoicing, and marketing. Focused on SMBs and solo operators.",
      "key_differentiators": ["Consumer-grade mobile UX", "Built-in marketing features", "Competitive pricing", "Strong community/brand in home services"],
      "why_included": "Direct competitor in the SMB home services segment. Strong mobile product often cited alongside Jobber by buyers."
    }
  ],
  "suggested_additions": [],
  "deck_competitors_excluded": [],
  "candidate_axes": [
    {
      "pair_id": "pair_1",
      "x_axis": "SMB Focus",
      "y_axis": "Scheduling & Dispatch Depth",
      "rationale": "Reveals the core tension in this market: competitors designed for enterprise vs. SMB, and those with broad platform scope vs. deep scheduling specialization. Cadence should differentiate on both dimensions — SMB-native and scheduling-depth-first."
    },
    {
      "pair_id": "pair_2",
      "x_axis": "Time to Value (Onboarding Speed)",
      "y_axis": "Platform Breadth (Full FSM Suite vs. Core Scheduling)",
      "rationale": "SMB buyers care deeply about how fast they can get running. ServiceTitan's breadth creates onboarding friction; simpler tools onboard faster. Cadence's hypothesis is that SMBs want fast onboarding more than full-suite breadth."
    },
    {
      "pair_id": "pair_3",
      "x_axis": "Pricing Accessibility",
      "y_axis": "Workflow Automation Depth",
      "rationale": "Pricing is a real gating factor for SMBs. Workflow automation (intelligent dispatching, route optimization, AI scheduling) is an emerging differentiator. Shows whether competitors trade off affordability for automation or vice versa."
